-- OpenLua - OneLua splash module demo.
--
--   splash.show()              -- bundled assets/splash.png
--   splash.show(path)          -- one image
--   splash.show({path, path})  -- slideshow, about 2 s per image
--   splash.old()               -- bundled assets/splash_old.png
--   splash.oldschool()         -- original OSLib-style tribute screen
--
-- A fresh Cross, Circle or Start press advances to the next image.
-- Missing images are skipped; with no loadable image a built-in
-- geometric screen is shown.  Assets are generated by tools/gen_splash.py.
--
-- The post-splash screen proves that the normal 2D GE state still works.

splash.show()
splash.old()
splash.oldschool()
splash.show({
    "assets/splash.png",
    "assets/splash_old.png",
})

local f = font.new("assets/font.png", 8, 16)
if f then
    screen.font(f)
end

local orange = color.new(235, 112, 42)
local teal   = color.new(48, 180, 160)
local white  = color.new(238, 240, 246)
local muted  = color.new(120, 132, 154)

while true do
    screen.clear(color.new(10, 14, 26))
    draw.fillrect(0, 0, 480, 4, orange)
    draw.fillrect(0, 268, 480, 4, teal)

    if f then
        screen.print(24, 52, "Splash demo complete", f, white)
        screen.print(24, 88, "splash.show / old / oldschool", f, orange)
        screen.print(24, 112, "image, table and fallback paths", f, muted)
        screen.print(24, 148, "2D GE state restored", f, teal)
        screen.print(24, 196, "Cross / Circle / Start advances", f, muted)
    end

    draw.rect(16, 40, 448, 200, color.new(44, 52, 72))
    screen.flip()
end
